package dev.mando;
import java.net.URI;import java.net.http.*;import java.time.Duration;import java.util.regex.*;
public final class UpdateChecker{
 private final MandoPlugin plugin;public UpdateChecker(MandoPlugin p){plugin=p;}
 public void checkAsync(){if(!plugin.getConfig().getBoolean("updates.enabled",true))return;String channel=plugin.getConfig().getString("updates.channel","STABLE").toUpperCase();String endpoint=channel.equals("TEST")?"https://api.github.com/repos/Italoplcl/comandos/releases":"https://api.github.com/repos/Italoplcl/comandos/releases/latest";try{HttpRequest q=HttpRequest.newBuilder(URI.create(endpoint)).timeout(Duration.ofSeconds(5)).header("Accept","application/vnd.github+json").header("User-Agent","Mando-UpdateChecker").build();HttpClient.newHttpClient().sendAsync(q,HttpResponse.BodyHandlers.ofString()).thenAccept(r->{if(r.statusCode()<200||r.statusCode()>=300){plugin.getLogger().warning("Update checker: GitHub respondió "+r.statusCode());return;}Matcher m=Pattern.compile("\\\"tag_name\\\"\\s*:\\s*\\\"([^\\\"]+)").matcher(r.body());if(m.find())plugin.getLogger().info("GitHub ("+channel+"): última versión publicada "+m.group(1)+" | instalada "+plugin.getPluginMeta().getVersion());else plugin.getLogger().info("GitHub: no hay una release "+channel.toLowerCase()+" publicada para comparar.");}).exceptionally(ex->{plugin.getLogger().warning("No se pudo comprobar actualizaciones: "+ex.getMessage());return null;});}catch(Exception ex){plugin.getLogger().warning("Update checker no disponible: "+ex.getMessage());}}
}